"use client";

import { useState, useTransition } from "react";
import { useTimeout } from "@/lib/use-timeout";
import { appUpdate, type AppUpdateState } from "./app-update-actions";

const button = "min-h-10 rounded-lg border border-border px-4 py-2 text-sm font-medium hover:bg-muted disabled:opacity-50";
const primary = "min-h-10 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50";

function describe(state: AppUpdateState) {
  switch (state.state) {
    case "checking": return "Checking for updates…";
    case "current": return `You have the latest version.`;
    case "available": return state.installs
      ? `Moneo ${state.latest} is available. Updating downloads it, restarts Moneo and keeps all your data.`
      : `Moneo ${state.latest} is available. Download it from GitHub and install it over this one; your data stays.`;
    case "downloading": return `Downloading Moneo ${state.latest}… ${state.percent ?? 0}%`;
    case "installing": return `Installing Moneo ${state.latest}. Moneo closes and opens again by itself in a moment.`;
    case "error": return state.error;
    default: return null;
  }
}

export function AppUpdate({ initial }: { initial: AppUpdateState }) {
  const [state, setState] = useState(initial);
  const [pending, start] = useTransition();
  const run = (action: "check" | "install") => start(async () => setState(await appUpdate(action, state)));
  const working = state.state === "downloading" || state.state === "installing";
  useTimeout(async () => setState(await appUpdate("status", state).catch(() => state)), working ? 1_000 : null, state);
  const text = describe(state);
  return <section id="updates" aria-labelledby="updates-title" className="scroll-mt-20 rounded-xl border border-border bg-card p-6">
    <h2 id="updates-title" className="text-sm font-medium">App updates</h2>
    <p className="mt-1 text-sm text-muted-foreground">This is Moneo {state.current}. Moneo checks for a new version only when you ask, and your data stays on this computer when it updates.</p>
    {text && <p role={state.state === "error" ? "alert" : "status"} className={`mt-3 text-sm ${state.state === "error" ? "text-danger" : ""}`}>{text}</p>}
    {state.message && <p role="alert" className="mt-3 text-sm text-danger">{state.message}</p>}
    {state.state === "downloading" && <progress className="mt-3 h-2 w-full max-w-sm accent-primary" max={100} value={state.percent ?? 0} aria-label="Download progress" />}
    <div className="mt-3 flex flex-wrap gap-2">
      {state.state === "available" && <button type="button" disabled={pending} className={primary} onClick={() => run("install")}>
        {state.installs ? `Update to ${state.latest}` : `Download ${state.latest}`}
      </button>}
      {!working && <button type="button" disabled={pending || state.state === "checking"} className={button} onClick={() => run("check")}>
        {pending || state.state === "checking" ? "Checking…" : "Check for updates"}
      </button>}
    </div>
  </section>;
}
"use server";

import { headers } from "next/headers";
import { requireWorkspace } from "@/lib/auth";
import { desktopUpdate, type UpdateStatus } from "@/lib/desktop-bridge";
import { fromRemoteDevice } from "@/lib/remote-device";

export type AppUpdateState = UpdateStatus & { message?: string };

export async function appUpdate(action: "status" | "check" | "install", previous: AppUpdateState): Promise<AppUpdateState> {
  await requireWorkspace();
  if (action !== "status" && fromRemoteDevice(await headers())) return { ...previous, message: "Update Moneo from the computer it runs on." };
  try { return await desktopUpdate(action) ?? { ...previous, message: "Updates are for the Moneo app." }; }
  catch { return previous.state === "installing" ? previous : { ...previous, message: "Moneo could not answer. Try again." }; }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { desktopBridgeUrl } from "@/lib/env";

const bridge = desktopBridgeUrl;
export const isDesktop = () => Boolean(bridge());

const CONTINUE_PAGE = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Return to Moneo</title>"
  + "<style>body{font:16px/1.5 system-ui,sans-serif;max-width:32rem;margin:15vh auto;padding:0 1rem;color:#222;background:#fff}@media (prefers-color-scheme:dark){body{color:#eee;background:#0f1011}}</style>"
  + "<body><h1>Continue in Moneo</h1><p>The result is now open in the Moneo app. You can close this browser tab.</p></body></html>";

export async function connectionReturn(base: string | URL, path: string) {
  const url = bridge();
  if (url) {
    const handedToTheApp = await fetch(`${url}/return`, { method: "POST", headers: { "x-moneo-return": path }, signal: AbortSignal.timeout(10_000) }).then(response => response.ok, () => false);
    if (handedToTheApp) return new Response(CONTINUE_PAGE, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'" },
    });
  }
  return NextResponse.redirect(new URL(path, base), 303);
}

const updateStatus = z.object({
  current: z.string(),
  state: z.enum(["idle", "checking", "current", "available", "downloading", "installing", "error"]),
  latest: z.string().optional(),
  percent: z.number().optional(),
  error: z.string().optional(),
  installs: z.boolean(),
});
export type UpdateStatus = z.infer<typeof updateStatus>;

export async function desktopUpdate(action: "status" | "check" | "install"): Promise<UpdateStatus | null> {
  const url = bridge();
  if (!url) return null;
  const response = await fetch(`${url}/update${action === "status" ? "" : `/${action}`}`, {
    method: action === "status" ? "GET" : "POST",
    signal: AbortSignal.timeout(60_000),
  });
  if (!response.ok) throw new Error(`The desktop app answered ${response.status}`);
  return updateStatus.parse(await response.json());
}

const chosenFolder = z.object({ path: z.string().min(1).nullable() });

export async function desktopChooseFolder(): Promise<string | null> {
  const url = bridge();
  if (!url) return null;
  const response = await fetch(`${url}/choose-folder`, { method: "POST", signal: AbortSignal.timeout(10 * 60_000) });
  if (!response.ok) throw new Error(`The desktop app answered ${response.status}`);
  return chosenFolder.parse(await response.json()).path;
}

const rendered = z.object({ png: z.string(), result: z.unknown() });

export async function desktopRender(request: { path: string; width: number; height: number; full: boolean; script: string }) {
  const url = bridge();
  if (!url) return null;
  const response = await fetch(`${url}/render`, { method: "POST", body: JSON.stringify(request), signal: AbortSignal.timeout(30_000) });
  if (!response.ok) throw new Error(`The desktop app answered ${response.status}`);
  const { png, result } = rendered.parse(await response.json());
  return { png: Buffer.from(png, "base64"), result };
}
import { app } from "electron";
import { autoUpdater } from "electron-updater";
import { z } from "zod";

export type UpdateStatus = {
  current: string;
  state: "idle" | "checking" | "current" | "available" | "downloading" | "installing" | "error";
  latest?: string;
  percent?: number;
  error?: string;
  installs: boolean;
};

const RELEASES = "https://github.com/indkhan/Moneo/releases";

const canInstall = () => process.platform === "win32" || (process.platform === "linux" && Boolean(process.env.APPIMAGE));

export function createUpdater(options: {
  log(line: string): void;
  openExternal(url: string): Promise<void>;
  relaunchAfterQuit(execPath: string): void;
  feed?: string;
}) {
  let status: UpdateStatus = { current: app.getVersion(), state: "idle", installs: canInstall() };
  const set = (patch: Partial<UpdateStatus>) => { status = { ...status, ...patch }; return status; };
  const failed = (error: unknown) => {
    const message = error instanceof Error ? error.message : String(error);
    options.log(`Update failed: ${message}`);
    if (/No published versions/i.test(message)) return set({ state: "current", latest: undefined, error: undefined });
    if (/app-update\.yml/.test(message)) return set({ state: "error", error: "Updates work in the installed Moneo app." });
    return set({ state: "error", error: "Moneo could not reach its releases on GitHub, or the download failed. Check the internet connection and try again." });
  };

  autoUpdater.autoDownload = false;
  autoUpdater.autoInstallOnAppQuit = false;
  autoUpdater.logger = { info: options.log, warn: options.log, error: options.log, debug: () => {} };
  if (options.feed) autoUpdater.setFeedURL({ provider: "generic", url: options.feed });
  autoUpdater.on("download-progress", progress => { if (status.state === "downloading") set({ percent: Math.floor(progress.percent) }); });
  autoUpdater.on("error", error => { if (status.state === "installing") failed(error); });

  let checking: Promise<UpdateStatus> | undefined;
  function check() {
    if (status.state === "downloading" || status.state === "installing") return Promise.resolve(status);
    checking ??= (async () => {
      set({ state: "checking", error: undefined });
      try {
        if (!options.feed) {
          const response = await fetch("https://api.github.com/repos/indkhan/Moneo/releases?per_page=100", {
            headers: { Accept: "application/vnd.github+json" },
            signal: AbortSignal.timeout(15000),
          });
          if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
          const releases = z.array(z.object({
            draft: z.boolean(), prerelease: z.boolean(),
            assets: z.array(z.object({ name: z.string(), browser_download_url: z.url() })),
          })).parse(await response.json());
          const metadata = process.platform === "win32" ? "latest.yml" : process.platform === "darwin" ? "latest-mac.yml" : "latest-linux.yml";
          const asset = releases.filter(release => !release.draft && !release.prerelease)
            .flatMap(release => release.assets.filter(item => item.name === metadata))[0];
          if (!asset) return set({ state: "current", latest: undefined });
          autoUpdater.setFeedURL({ provider: "generic", url: asset.browser_download_url.slice(0, asset.browser_download_url.lastIndexOf("/") + 1) });
        }
        const result = await autoUpdater.checkForUpdates();
        if (!result) return set({ state: "error", error: "Updates work in the installed Moneo app." });
        const latest = result.updateInfo.version;
        return set({ state: result.isUpdateAvailable ? "available" : "current", latest });
      } catch (error) { return failed(error); }
    })().finally(() => { checking = undefined; });
    return checking;
  }

  async function install() {
    if (status.state !== "available" || !status.latest) return status;
    if (!status.installs) {
      await options.openExternal(`${RELEASES}/tag/v${status.latest}`);
      return status;
    }
    set({ state: "downloading", percent: 0 });
    void autoUpdater.downloadUpdate().then(() => {
