export const SERVICE_KEY_VARIABLES = ["OPENAI_API_KEY", "OPENROUTER_API_KEY", "ENABLE_BANKING_APP_ID", "ENABLE_BANKING_PRIVATE_KEY"] as const;
export type ServiceKeyVariable = (typeof SERVICE_KEY_VARIABLES)[number];
export const serviceKeyFromEnv = (variable: ServiceKeyVariable) => read(variable);

export const SETUP_VARIABLES = ["SUPABASE_DB_URL", "SUPABASE_SERVICE_ROLE_KEY", "NEXT_PUBLIC_SUPABASE_URL", "MONEO_OWNER_EMAIL", "MONEO_OWNER_PASSWORD", "BANK_TOKEN_ENCRYPTION_KEY", "CRON_SECRET"] as const;
export type SetupVariable = (typeof SETUP_VARIABLES)[number];
export const isSetupVariableSet = (variable: SetupVariable) => Boolean(read(variable));

export const childProcessEnv = (): NodeJS.ProcessEnv => ({ ...process.env });
import { useEffect, useRef } from "react";

const taskReportsItsOwnFailure = () => undefined;

type PollTask = (signal: AbortSignal) => void | Promise<void>;

export function usePolling(task: PollTask, ms: number, active: boolean, options: { immediate?: boolean } = {}) {
  const latest = useRef(task);
  useEffect(() => { latest.current = task; });
  const { immediate = false } = options;
  useEffect(() => {
    if (!active) return;
    let timer: ReturnType<typeof setInterval> | undefined;
    let running: AbortController | undefined;
    const run = () => {
      if (running) return;
      const controller = running = new AbortController();
      const release = () => { if (running === controller) running = undefined; };
      try {
        const result = latest.current(controller.signal);
        if (result) result.catch(taskReportsItsOwnFailure).finally(release); else release();
      } catch { release(); }
    };
    const stop = () => { clearInterval(timer); timer = undefined; running?.abort(); running = undefined; };
    const start = () => { if (!timer && !document.hidden) timer = setInterval(run, ms); };
    const onVisibility = () => { stop(); if (document.hidden) return; run(); start(); };
    if (immediate && !document.hidden) run();
    start();
    document.addEventListener("visibilitychange", onVisibility);
    return () => { stop(); document.removeEventListener("visibilitychange", onVisibility); };
  }, [active, ms, immediate]);
}
import { useCallback, useEffect, useRef } from "react";

export function useTimeout(callback: () => void, delayMs: number | null, restartKey?: unknown) {
  const latest = useRef(callback);
  useEffect(() => { latest.current = callback; });
  useEffect(() => {
    if (delayMs === null) return;
    const timer = setTimeout(() => latest.current(), delayMs);
    return () => clearTimeout(timer);
  }, [delayMs, restartKey]);
}

export function useDelay() {
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const cancel = useCallback(() => clearTimeout(timer.current), []);
  useEffect(() => cancel, [cancel]);
  const after = useCallback((run: () => void, delayMs: number) => {
    clearTimeout(timer.current);
    timer.current = setTimeout(run, delayMs);
  }, []);
  return [after, cancel] as const;
}
import { unstable_rethrow } from "next/navigation";
import { z } from "zod";
import { readableError } from "@/lib/readable-error";

export type SafeState = { error?: string };

const STALE_VERSION = /\bchanged(; (refresh|reload|retry)\b.*)?$/i;
const STALE_GUIDANCE = "This changed since you opened it. Refresh and review it, then try again.";

export async function safely(form: FormData, action: (form: FormData) => Promise<unknown>): Promise<SafeState> {
  try {
    await action(form);
    return {};
  } catch (cause) {
    unstable_rethrow(cause);
    if (cause instanceof z.ZodError) return { error: cause.issues[0]?.message ?? "Check the form and try again" };
    const error = readableError(cause);
    return { error: STALE_VERSION.test(error) ? STALE_GUIDANCE : error };
  }
}
