import { mkdirSync, writeFileSync } from "node:fs";
import { chromium, devices } from "@playwright/test";

const [runsArg, ...targetArgs] = process.argv.slice(2);
const targets = targetArgs.map(arg => { const [label, base] = [arg.slice(0, arg.indexOf("=")), arg.slice(arg.indexOf("=") + 1)]; return { label, base }; });
if (!targets.length || !targets.every(target => target.label && target.base)) throw new Error("usage: node scripts/perf-pages.mjs <runs> <label=baseUrl>...");
const runs = Number(runsArg);
const PAGES = ["/", "/ai", "/ai/artifacts", "/ai/activity", "/money/accounts", "/money/transactions", "/money/recurring", "/money/wealth", "/plan", "/plan/spending", "/settings"];
const VIEWPORTS = { desktop: { viewport: { width: 1440, height: 900 } }, mobile: { ...devices["Pixel 7"] } };

const probe = () => {
  const m = (window.__perf = { lcp: 0, cls: 0, longTasks: 0, longTaskMs: 0, heading: 0 });
  new PerformanceObserver(list => { for (const e of list.getEntries()) m.lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
  new PerformanceObserver(list => { for (const e of list.getEntries()) if (!e.hadRecentInput) m.cls += e.value; }).observe({ type: "layout-shift", buffered: true });
  new PerformanceObserver(list => { for (const e of list.getEntries()) { m.longTasks++; m.longTaskMs += e.duration; } }).observe({ type: "longtask", buffered: true });
  const tick = () => {
    const h = document.querySelector("main h1, h1");
    if (h && h.getBoundingClientRect().height > 0 && getComputedStyle(h).visibility !== "hidden") m.heading = performance.now(); else requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
};

const median = values => { const sorted = values.filter(v => v != null).sort((a, b) => a - b); return sorted.length ? sorted[Math.floor(sorted.length / 2)] : null; };
const browser = await chromium.launch();
const results = Object.fromEntries(targets.map(target => [target.label, {}]));
for (const [vpName, vp] of Object.entries(VIEWPORTS)) {
  for (const path of PAGES) {
    const samples = Object.fromEntries(targets.map(target => [target.label, []]));
    for (let run = -1; run < runs; run++) {
      for (const { label, base } of targets) {
        const context = await browser.newContext({ ...vp, baseURL: base, storageState: "e2e/.auth.json" });
        await context.addInitScript(probe);
        const page = await context.newPage();
        let transfer = 0, js = 0, requests = 0;
        page.on("requestfinished", async request => {
          try {
            const sizes = await request.sizes(); const bytes = sizes.responseBodySize + sizes.responseHeadersSize;
            transfer += bytes; requests++;
            if (request.resourceType() === "script") js += sizes.responseBodySize;
          } catch {}
        });
        const response = await page.goto(path, { waitUntil: "load" }).catch(() => null);
        await page.waitForTimeout(2000);
        const m = await page.evaluate(() => {
          const nav = performance.getEntriesByType("navigation")[0];
          const fcp = performance.getEntriesByName("first-contentful-paint")[0];
          return { ...window.__perf, ttfb: nav.responseStart, fcp: fcp?.startTime ?? null, load: nav.loadEventEnd };
        });
        if (run >= 0) samples[label].push({ ...m, status: response?.status(), final: new URL(page.url()).pathname, transferKB: transfer / 1024, jsKB: js / 1024, requests });
        await context.close();
import { expect, test } from "@playwright/test";
import { e2eStorageStatePath } from "./fixtures";

const signedIn = e2eStorageStatePath();
if (signedIn) test.use({ storageState: signedIn });
test.skip(!signedIn, "Needs the QA session (scripts/e2e-auth.mjs)");

const pem = "-----BEGIN PRIVATE KEY-----\nMIIsynthetic\n-----END PRIVATE KEY-----\n";

test("a new owner connects a first and a second bank from Accounts without visiting Settings", async ({ page }) => {
  let configured = false;
  const saved: unknown[] = [];
  const connections: unknown[] = [];
  const bank = (id: string, name: string) => ({ id, aspsp_name: name, aspsp_country: "DE", status: "active", valid_until: "2027-05-01T00:00:00Z", last_synced_at: null,
    sync_started_at: null, last_error: null, problem: null, next_sync_at: null, accounts: [{ provider_account_uid: `${id}-1`, account_name: `${name} Girokonto`, currency_code: "EUR", last_booked_on: null }],
    sync: { running: false, imports: [] } });
  await page.route("**/api/bank/connections", route => route.fulfill({ json: {
    configured, credentials: configured ? { source: "app", hint: "f00d" } : { source: null, hint: null },
    redirectUrl: "https://localhost:3443/api/bank/callback", connections } }));
  await page.route("**/api/scalable/connections", route => route.fulfill({ json: { configured: true, connection: null } }));
  await page.route("**/api/bank/credentials", async route => {
    saved.push(route.request().postDataJSON());
    configured = true;
    await route.fulfill({ json: { saved: true } });
  });
  await page.route("**/api/bank/aspsps?country=*", route => route.fulfill({ json: { banks: [{ name: "Testbank", country: "DE" }, { name: "Other Bank", country: "DE" }] } }));
  const opened: string[] = [];
  await page.route("**/api/bank/connect", async route => {
    const { aspspName } = route.request().postDataJSON();
    opened.push(aspspName);
    connections.unshift(bank(`b${connections.length + 1}`, aspspName));
    await route.fulfill({ json: { url: "/money/accounts?bank=connected#connected" } });
  });

  await page.goto("/money/accounts?connect=bank#connected");
  const flow = page.getByRole("group", { name: "Connect a bank" });
  await expect(flow.getByText("https://localhost:3443/api/bank/callback")).toBeVisible();
  await flow.getByLabel("App ID").fill("app-synthetic");
  await flow.getByLabel("Or upload the .pem file").setInputFiles({ name: "app-synthetic.pem", mimeType: "application/x-pem-file", buffer: Buffer.from(pem) });
  await expect(flow.getByLabel("Private key")).toHaveValue(pem);
import { defineConfig, devices } from "@playwright/test";
import { existsSync } from "node:fs";
import { e2eStorageStatePath } from "./e2e/fixtures";

if (existsSync(".env.qa")) process.loadEnvFile(".env.qa");
const production = process.env.E2E_PRODUCTION_BUILD === "1";
const external = process.env.E2E_BASE_URL;

export default defineConfig({
  testDir: "./e2e",
