import { mkdirSync } from "node:fs";
import { chromium, devices } from "@playwright/test";

const offer = { current: "0.5.0", latest: "0.6.0", notes: "Moneo Desktop v0.6.0.\n\n- Faster imports\n- Clearer bank errors", url: "https://github.com/indkhan/Moneo/releases/tag/v0.6.0" };
const desktop = state => ({ ...offer, kind: "desktop", state, installs: true, percent: state === "downloading" ? 42 : undefined });
const VIEWS = [["light", "light", devices["Desktop Chrome"]], ["dark", "dark", devices["Desktop Chrome"]], ["mobile", "light", devices["iPhone 13"]]];
const shots = [
  ["before", 3102, "topbar", "/", undefined],
  ["before", 3102, "settings", "/settings", undefined],
  ["after", 3101, "topbar-none", "/", null],
  ["after", 3101, "topbar-update", "/", { ...offer, kind: "source" }],
  ["after", 3101, "dialog-source", "/", { ...offer, kind: "source" }],
  ["after", 3101, "dialog-desktop", "/", desktop("available")],
  ["after", 3101, "dialog-downloading", "/", desktop("downloading")],
  ["after", 3101, "dialog-restart", "/", desktop("downloaded")],
  ["after", 3101, "settings", "/settings", null],
];
const browser = await chromium.launch();
let failed = false;
for (const [label, port, name, path, update] of shots) {
  mkdirSync(`.qa/shots/${label}`, { recursive: true });
  for (const [view, theme, device] of VIEWS) {
    const base = `http://localhost:${port}`;
    const context = await browser.newContext({ ...device, baseURL: base, storageState: "e2e/.auth.json", extraHTTPHeaders: { "x-moneo-test": "1" }, reducedMotion: "reduce", colorScheme: theme });
    await context.addCookies([{ name: "moneo-theme", value: theme, url: base }]);
    const page = await context.newPage();
    const problems = [];
    page.on("pageerror", error => problems.push(error.message));
    page.on("response", reply => { if (reply.status() >= 400) problems.push(`${reply.status()} ${new URL(reply.url()).pathname}`); });
    if (update !== undefined) await page.route("**/api/app-update", route => route.fulfill({ json: { update } }));
    await page.goto(path, { waitUntil: "networkidle" });
    if (name.startsWith("dialog")) {
      await page.getByRole("button", { name: "Update", exact: true }).click();
      await page.getByRole("dialog", { name: "Update Moneo" }).waitFor();
    }
    await page.screenshot({ path: `.qa/shots/${label}/${name}-${view}.png`, fullPage: name === "settings", animations: "disabled" });
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    if (problems.length || overflow > 0) { failed = true; console.log(label, name, view, problems, overflow); }
    await context.close();
  }
}
await browser.close();
console.log(failed ? "problems" : "ok");
