import http from "node:http";

const port = Number(process.argv[2] ?? 47999);
let status = { current: "0.5.0", state: "idle", installs: true };
let timer;
const offered = { latest: "0.6.0", notes: "Moneo Desktop v0.6.0.\n\n- Faster imports\n- Clearer bank errors" };

http.createServer((req, res) => {
  const route = `${req.method} ${req.url.replace(/^\/token/, "")}`;
  console.log(route, status.state);
  if (route === "POST /reset") { clearInterval(timer); status = { current: "0.5.0", state: "idle", installs: true }; }
  if (route === "POST /update/check" && status.state === "idle") status = { ...status, ...offered, state: "available" };
  if (route === "POST /update/install") {
    if (status.state === "downloaded") status = { ...status, state: "installing" };
    else if (status.state === "available") {
      status = { ...status, state: "downloading", percent: 0 };
      timer = setInterval(() => {
        const percent = status.percent + 20;
        status = percent >= 100 ? { ...status, state: "downloaded", percent: 100 } : { ...status, percent };
        if (percent >= 100) clearInterval(timer);
      }, 900);
    }
  }
  res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(status));
}).listen(port, "127.0.0.1", () => console.log("bridge ready", port));

