import { mkdirSync } from "node:fs";
import { chromium, devices } from "@playwright/test";

const VIEWS = [["light", "light", devices["Desktop Chrome"]], ["dark", "dark", devices["Desktop Chrome"]], ["mobile", "light", devices["iPhone 13"]]];
const reset = () => fetch("http://127.0.0.1:47999/token/reset", { method: "POST" });
const browser = await chromium.launch();
mkdirSync(".qa/shots/before", { recursive: true });
mkdirSync(".qa/shots/after", { recursive: true });

for (const [view, theme, device] of VIEWS) {
  const open = async port => {
    const base = `http://localhost:${port}`;
    const context = await browser.newContext({ ...device, baseURL: base, storageState: "e2e/.auth.json", extraHTTPHeaders: { "x-moneo-test": "1" }, reducedMotion: "reduce", colorScheme: theme });
    await context.addCookies([{ name: "moneo-theme", value: theme, url: base }]);
    const page = await context.newPage();
    page.on("pageerror", error => console.log("pageerror", error.message));
    page.on("response", reply => { if (reply.status() >= 400) console.log(reply.status(), new URL(reply.url()).pathname); });
    return [context, page];
  };
  await reset();
  let [context, page] = await open(3104);
  await page.goto("/settings", { waitUntil: "networkidle" });
  await page.screenshot({ path: `.qa/shots/before/settings-desktop-app-${view}.png`, animations: "disabled" });
  await context.close();

  await reset();
  [context, page] = await open(3103);
  await page.goto("/settings", { waitUntil: "networkidle" });
  await page.getByRole("button", { name: "Update", exact: true }).waitFor();
  console.log(view, "settings updates section", await page.locator("#updates").count());
  await page.screenshot({ path: `.qa/shots/after/settings-desktop-app-${view}.png`, animations: "disabled" });
  await page.getByRole("button", { name: "Update", exact: true }).click();
  const dialog = page.getByRole("dialog", { name: "Update Moneo" });
  await dialog.getByRole("button", { name: "Download 0.6.0" }).waitFor();
  await page.screenshot({ path: `.qa/shots/after/dialog-desktop-${view}.png`, animations: "disabled" });
  await dialog.getByRole("button", { name: "Download 0.6.0" }).click();
  await dialog.getByText(/Downloading… [4-8]0%/).waitFor();
  console.log(view, "accent", await dialog.locator("progress").evaluate(node => getComputedStyle(node).accentColor));
  await page.screenshot({ path: `.qa/shots/after/dialog-downloading-${view}.png` });
  await dialog.getByRole("button", { name: "Restart to install" }).waitFor({ timeout: 20_000 });
  await page.screenshot({ path: `.qa/shots/after/dialog-restart-${view}.png`, animations: "disabled" });
  await dialog.getByRole("button", { name: "Restart to install" }).click();
  await dialog.getByText("Installing.", { exact: false }).waitFor();
  console.log(view, "download then restart then installing: ok");
  await context.close();
}
await browser.close();

